<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Update;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\UserPersonalApiKeyRef;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Service\Visibility\UserPersonalApiKeyVisibilityService;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\Gateway\UserPersonalApiKeyWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserPersonalApiKeyUpdateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserPersonalApiKeyVisibilityService $visibility,
        private readonly UserPersonalApiKeyWriteGateway $writer,
    ) {
    }

    public function allowUpdate(?UserPersonalApiKeyRef $ref = null): Allow
    {
        $this->logDebug("Check allow update usecase for User personal api key");
        $span = $this->startSpan("Check allow update usecase for User personal api key");
        try {
            $result = $this->dispatcher->dispatch(new UserPersonalApiKeyUpdateAllowDecision(Allow::allowed('update', 'Allowed to update by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fixedFields(?UserPersonalApiKeyRef $ref = null): array
    {
        $this->logDebug("Check fixed fields for update usecase for User personal api key");
        $span = $this->startSpan("Check fixed fields for update usecase for User personal api key");
        try {
            return $this->visibility->fieldsToFix($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function update(string $uid, UserPersonalApiKeyUpdateParams $params): UserPersonalApiKeyUpdateResult
    {
        $this->logDebug("Run update usecase for User personal api key");
        $span = $this->startSpan("Run update usecase for User personal api key");
        try {
            $ref = new UserPersonalApiKeyRef($uid);
            $allow = $this->allowUpdate($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to update User personal api key');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new UserPersonalApiKeyUpdateCheck($params, $original));
            $enriched = $this->dispatcher->dispatch(new UserPersonalApiKeyUpdateEnrich($params, $original, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $modified = $original->update($input);
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new UserPersonalApiKeyUpdateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
